function showCameraConfig(camera){openModal(`Camera Configuration · ${camera}`,`<div class="wizard-head"><span class="wizard-step active">1 Source</span><span class="wizard-step">2 Stream</span><span class="wizard-step">3 Business Links</span><span class="wizard-step">4 AI Role</span><span class="wizard-step">5 Test</span></div><div class="form-grid"><div class="field"><label>Camera Type</label><select class="select"><option>RTSP / IP Camera</option><option>ONVIF</option><option>USB / Webcam</option><option>DVR / NVR Channel</option></select></div><div class="field"><label>Camera Role</label><select class="select"><option>Cash Counter</option><option>Entrance</option><option>Medicine Shelf</option><option>Storage / Restricted</option><option>Shop Floor</option></select></div><div class="field"><label>Resolution</label><select class="select"><option>1080p</option><option>720p</option><option>Auto</option></select></div><div class="field"><label>AI Analysis FPS</label><select class="select"><option>10 FPS</option><option>15 FPS</option><option>5 FPS</option></select></div><div class="field" style="grid-column:1/-1"><label>Stream URL / Device</label><input class="input" value="rtsp://••••••••@192.168.1.22:554/stream1"></div><div class="field"><label>Linked POS Counter</label><select class="select"><option>Counter 1</option><option>Counter 2</option><option>Not linked</option></select></div><div class="field"><label>Linked Cash Drawer</label><select class="select"><option>Drawer 1</option><option>Drawer 2</option><option>Not linked</option></select></div><div class="field"><label>Inventory Location</label><select class="select"><option>Rack A / Counter Stock</option><option>Rack B</option><option>High Value Rack</option><option>Not linked</option></select></div><div class="field"><label>Shift Context</label><select class="select"><option>Use POS login + shift assignment</option><option>Counter assignment only</option><option>No employee context</option></select></div><div class="field"><label>Recording Mode</label><select class="select"><option>AI events only</option><option>Continuous</option><option>Motion + AI events</option><option>Monitoring only</option></select></div><div class="field"><label>Privacy Mode</label><select class="select"><option>Anonymous person tracking</option><option>Detection only</option></select></div></div>`,`<button class="btn secondary" onclick="toast('Camera + business links test passed')">Test All Links</button><button class="btn primary" onclick="closeModal();toast('Camera configuration saved')">Save</button>`)}
function showSoftwareConnector(name,segment){openModal(`Connect ${name}`,`<div class="connector-title"><div class="software-logo large">${name.slice(0,2).toUpperCase()}</div><div><h3>${name}</h3><p>${segment} · Existing software connector wizard</p></div></div><div class="wizard-head"><span class="wizard-step active">1 Detect</span><span class="wizard-step">2 Access</span><span class="wizard-step">3 Map Data</span><span class="wizard-step">4 Test</span></div><div class="notice-card"><b>Important</b><span>Available connection methods differ by product/version. During real deployment MedGuard will use the supported route available at that shop: vendor API, read-only database/ODBC, scheduled export, or local bridge. We will not assume unsupported access.</span></div><div class="form-grid"><div class="field"><label>Connection Method</label><select class="select"><option>Auto Detect Local Installation</option><option>Vendor / Open API</option><option>Read-only Database / ODBC</option><option>CSV / Excel Scheduled Export</option><option>Shared Folder / Local Bridge</option><option>Manual Custom Connector</option></select></div><div class="field"><label>Installed On</label><select class="select"><option>This MedGuard PC</option><option>Billing / POS PC on LAN</option><option>Cloud account</option><option>Another server</option></select></div><div class="field"><label>Host / PC / URL</label><input class="input" placeholder="e.g. BILLING-PC or API endpoint"></div><div class="field"><label>Access Profile</label><select class="select"><option>Read-only (Recommended)</option><option>Read + approved sync actions</option></select></div></div><h3 style="margin-top:16px">Data to Sync</h3><div class="connector-data"><label><input type="checkbox" checked> Sales & bills</label><label><input type="checkbox" checked> Payment mode</label><label><input type="checkbox" checked> Medicine / item master</label><label><input type="checkbox" checked> Batch & expiry</label><label><input type="checkbox" checked> Stock movement</label><label><input type="checkbox" checked> Returns / cancellations</label><label><input type="checkbox" checked> Discounts / overrides</label><label><input type="checkbox"> Purchase / supplier data</label></div>`,`<button class="btn secondary" onclick="toast('Detection simulated: connector path available for configuration')">Detect / Test</button><button class="btn primary" onclick="closeModal();toast('${name} connector setup saved in frontend demo')">Save Connector</button>`)}
function runDiagnostics(){openModal('System Diagnostics',`<div class="diagnostic-console"><div>✓ Camera workers .......... 6/6</div><div>✓ POS sync ................ 4 sec</div><div>✓ Payment sync ............ 7 sec</div><div>✓ Inventory sync .......... 3 sec</div><div>✓ Event correlator ........ Running</div><div>✓ AI supervisor ........... Running</div><div>✓ Storage ................. 580 GB free</div><div>✓ Backup .................. Verified</div></div>`,`<button class="btn success" onclick="closeModal();toast('Diagnostics completed')">All Checks Passed</button>`)}
function simulateFailure(type){openModal(`${type} Failure State`,`<div class="failure-demo"><div class="failure-big">!</div><h2>${type} requires attention</h2><p>This is a frontend simulation showing the message an owner would receive. The production system will attempt safe automatic recovery where possible and clearly state which monitoring functions remain available.</p><div class="check-card"><div><b>Automatic recovery</b><br><span>Retry / reconnect policy started</span></div>${badge('IN PROGRESS','warning')}</div><div class="check-card"><div><b>Evidence safety</b><br><span>Existing clips and transaction data preserved</span></div>${badge('PROTECTED','success')}</div></div>`,`<button class="btn secondary" onclick="closeModal()">Dismiss</button><button class="btn primary" onclick="closeModal();toast('${type} recovery test completed')">Retry Now</button>`)}
function pageInvestigation(){const ev=new URLSearchParams(location.search).get('event')||'EV-2048';return `<div class="investigation-top"><div><a href="events.html" class="back-link">← Back to Events</a><div class="investigation-title"><h2>${ev} · Cash Drawer / Transaction Review</h2><span class="risk-score risk-high">84/100 High Review</span>${badge('96% signal confidence','success')}</div><p>Risk score is review priority. Confidence describes the underlying detector/correlation certainty; neither is proof of theft or misconduct.</p></div><div class="review-actions"><button class="btn secondary" onclick="setReviewFeedback('normal')">✓ Normal</button><button class="btn warning" onclick="setReviewFeedback('investigate')">⚠ Needs Investigation</button><button class="btn secondary" onclick="setReviewFeedback('false')">× False Alert</button><button class="btn primary" onclick="createIncidentCase('${ev}')">Create Case</button></div></div><div class="investigation-grid"><div class="card evidence-player"><div class="card-title-row"><div><h3>CCTV Evidence</h3><div class="subtitle">Cash Counter 1 · 11:28:00–11:28:45</div></div>${badge('Event Clip','danger')}</div><div class="video-sim"><div class="camera-feed"></div><div class="video-timestamp">11:28:13</div><div class="video-person person-a"></div><div class="video-counter-zone">CASH COUNTER ZONE</div><div class="play-button">▶</div></div><div class="player-controls"><button class="btn secondary">↺ 10s</button><button class="btn primary" onclick="toast('Video playback simulated')">▶ Play</button><button class="btn secondary">0.5×</button><button class="btn secondary">1×</button><button class="btn secondary">2×</button><input type="range" min="0" max="45" value="13"></div><div class="evidence-scale"><span>11:28:00</span><span class="event-marker">▲ Drawer Event</span><span>11:28:45</span></div></div><div class="card investigation-summary"><div class="card-title-row"><div><h3>Correlated Transaction</h3><div class="subtitle">Cross-system evidence</div></div>${badge('Mismatch','warning')}</div><div class="evidence-section"><h4>Billing</h4><div class="kv"><span>Active bill at event time</span><b>None</b></div><div class="kv"><span>Nearest bill</span><b>#B1839 · Cancelled</b></div><div class="kv"><span>Counter</span><b>Counter 1</b></div></div><div class="evidence-section"><h4>Payment</h4><div class="kv"><span>Cash sale</span><b>Not found</b></div><div class="kv"><span>UPI / Card</span><b>No matching payment</b></div></div><div class="evidence-section"><h4>Inventory</h4><div class="kv"><span>Stock movement</span><b>Not confirmed</b></div><div class="kv"><span>Medicine shelf event</span><b>None linked</b></div></div><div class="evidence-section"><h4>Camera AI Confidence</h4><div class="kv"><span>Person detection</span><b>97%</b></div><div class="kv"><span>Zone activity</span><b>95%</b></div><div class="kv"><span>Transaction correlation</span><b>100%</b></div><div class="kv"><span>Overall signal confidence</span><b>96%</b></div></div></div></div>${section('Evidence Timeline','Camera + business systems aligned on one clock')}<div class="card evidence-timeline"><div class="evidence-step normal"><div class="e-time">11:27:58</div><div class="e-dot"></div><div><b>Person approaches cash counter</b><p>Anonymous track #P-219 enters counter interaction zone.</p></div></div><div class="evidence-step alert"><div class="e-time">11:28:13</div><div class="e-dot"></div><div><b>Cash drawer activity detected</b><p>Drawer zone changed from closed-state pattern; no active cash bill found.</p></div></div><div class="evidence-step alert"><div class="e-time">11:28:15</div><div class="e-dot"></div><div><b>Transaction correlation failed</b><p>POS: no matching sale · Payments: no matching confirmation.</p></div></div><div class="evidence-step normal"><div class="e-time">11:28:18</div><div class="e-dot"></div><div><b>Evidence clip locked</b><p>15-second pre-event buffer and 30-second post-event segment preserved.</p></div></div><div class="evidence-step normal"><div class="e-time">11:28:20</div><div class="e-dot"></div><div><b>Owner review event created</b><p>Risk score 84 based on multiple signals, not a theft conclusion.</p></div></div></div><div class="grid grid-2" style="margin-top:16px"><div class="card"><h3>Why risk score is 84</h3><div class="risk-reason"><span>Drawer opened without active cash sale</span><b>+35</b></div><div class="risk-reason"><span>No matching payment confirmation</span><b>+25</b></div><div class="risk-reason"><span>Nearby bill was cancelled</span><b>+20</b></div><div class="risk-reason"><span>Owner Away monitoring boost</span><b>+4</b></div><div class="notice-card"><b>Interpretation</b><span>High review priority only. Human review is required before any conclusion.</span></div></div><div class="card"><h3>Human Review + Notes</h3><div class="feedback-grid"><button onclick="setReviewFeedback('normal')">✓ Normal</button><button onclick="setReviewFeedback('investigate')">⚠ Investigate</button><button onclick="setReviewFeedback('false')">× False Alert</button></div><textarea class="textarea" style="width:100%;min-height:110px;margin-top:10px" placeholder="Owner / manager notes..."></textarea><div class="kv"><span>Assigned to</span><b>Owner Admin</b></div><div class="kv"><span>Retention</span><b>30 days</b></div><button class="btn primary" onclick="toast('Investigation notes saved')">Save Notes</button></div></div>`}
let zoneEditorState={camera:'',mode:'select',points:[],selectedId:null,zones:[],lines:[],calibration:[]};
const ZONE_TYPES={
  'Cash Counter':{color:'#ffb93b',preset:'Cash Counter Protection',rules:['Counter unattended','Drawer activity','Customer waiting','Transaction mismatch']},
  'Medicine Shelf':{color:'#2fb3ff',preset:'Medicine Shelf Monitoring',rules:['Movement detected','No nearby bill','Stock mismatch']},
  'High-Value Medicines':{color:'#d86fd2',preset:'High Value Medicine',rules:['Movement detected','No nearby bill','Owner Away activity','After-hours access']},
  'Restricted Storage':{color:'#f05f6e',preset:'Storage Room Security',rules:['Presence detected','After-hours activity','Extended presence']},
  'Customer Queue':{color:'#7e6cff',preset:'Queue & Service',rules:['Queue count','Customer waiting']},
  'Entrance':{color:'#3de08b',preset:'Entrance Analytics',rules:['Entry count','Exit count','Crowd']},
  'Staff Area':{color:'#44b8c7',preset:'Operational Area',rules:['Presence','Unattended context']},
  'Ignore Zone':{color:'#7a8797',preset:'Ignore',rules:['Ignore all AI events']},
  'Custom':{color:'#0f6fff',preset:'Custom',rules:['Presence detected']}
};
function defaultZones(){return [
  {id:'z1',name:'Cash Counter',type:'Cash Counter',points:[[53,49],[90,49],[90,83],[53,83]],sensitivity:'High',schedule:'Shop Hours',delay:'30 sec',record:'AI events + buffer',preset:'Cash Counter Protection',shelf:'Counter Stock',pos:'Counter 1',drawer:'Drawer 1',rules:['Counter unattended','Drawer activity','Customer waiting','Transaction mismatch']},
  {id:'z2',name:'High-Value Medicines',type:'High-Value Medicines',points:[[7,18],[41,18],[41,64],[7,64]],sensitivity:'High',schedule:'Always',delay:'10 sec',record:'AI events + buffer',preset:'High Value Medicine',shelf:'High Value Rack',pos:'Not linked',drawer:'Not linked',rules:['Movement detected','No nearby bill','Owner Away activity','After-hours access']},
  {id:'z3',name:'Entrance Area',type:'Entrance',points:[[2,72],[22,72],[22,97],[2,97]],sensitivity:'Medium',schedule:'Shop Hours',delay:'Immediate',record:'Events only',preset:'Entrance Analytics',shelf:'Not linked',pos:'Not linked',drawer:'Not linked',rules:['Entry count','Exit count','Crowd']}
]}
function setZoneDrawMode(mode,btn){zoneEditorState.mode=mode;zoneEditorState.points=[];document.querySelectorAll('.zone-tool[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));if(btn)btn.classList.add('active');const help={select:'Select an existing zone from the list.',polygon:'Click 3 or more points around the exact area, then Finish Shape.',rectangle:'Click two opposite corners of the area.',line:'Click two points across the doorway. Direction follows first point → second point.',calibrate:'Click four floor reference points for perspective calibration.'};const h=document.getElementById('zoneHelp');if(h)h.textContent=help[mode]||help.select;renderDraftPoints()}
function zoneCanvasClick(e){if(['select'].includes(zoneEditorState.mode))return;const c=document.getElementById('zoneCanvas');if(!c)return;const r=c.getBoundingClientRect();const x=Math.max(0,Math.min(100,(e.clientX-r.left)/r.width*100));const y=Math.max(0,Math.min(100,(e.clientY-r.top)/r.height*100));zoneEditorState.points.push([x,y]);if(zoneEditorState.mode==='rectangle'&&zoneEditorState.points.length===2){finishCurrentShape()}else if(zoneEditorState.mode==='line'&&zoneEditorState.points.length===2){finishCurrentShape()}else if(zoneEditorState.mode==='calibrate'&&zoneEditorState.points.length===4){zoneEditorState.calibration=[...zoneEditorState.points];zoneEditorState.points=[];toast('Perspective reference area calibrated in frontend demo');setZoneDrawMode('select');renderZoneEditor()}else{renderDraftPoints()}const f=document.getElementById('finishZoneBtn');if(f)f.disabled=!(zoneEditorState.mode==='polygon'&&zoneEditorState.points.length>=3)}
function renderDraftPoints(){const layer=document.getElementById('zonePointLayer');if(!layer)return;layer.innerHTML=zoneEditorState.points.map((p,i)=>`<span class="draft-point" style="left:${p[0]}%;top:${p[1]}%">${i+1}</span>`).join('');const svg=document.getElementById('zoneSvg');if(svg)renderZoneSvg(svg)}
function finishCurrentShape(){const pts=zoneEditorState.points;if(zoneEditorState.mode==='polygon'&&pts.length<3)return toast('Polygon ke liye kam se kam 3 points select karo.');if(zoneEditorState.mode==='rectangle'&&pts.length===2){const [a,b]=pts;zoneEditorState.points=[[a[0],a[1]],[b[0],a[1]],[b[0],b[1]],[a[0],b[1]]]}if(zoneEditorState.mode==='line'){const id='l'+Date.now();zoneEditorState.lines.push({id,name:'Entry / Exit Line '+(zoneEditorState.lines.length+1),points:[...zoneEditorState.points],direction:'First point → second point'});zoneEditorState.points=[];setZoneDrawMode('select');renderZoneEditor();return toast('Entry / Exit line added.')}const id='z'+Date.now();const type=document.getElementById('newZoneTypeQuick')?.value||'Custom';const meta=ZONE_TYPES[type]||ZONE_TYPES.Custom;zoneEditorState.zones.push({id,name:type+' '+(zoneEditorState.zones.length+1),type,points:[...zoneEditorState.points],sensitivity:'Medium',schedule:'Shop Hours',delay:'30 sec',record:'AI events + buffer',preset:meta.preset,shelf:'Not linked',pos:'Not linked',drawer:'Not linked',rules:[...meta.rules]});zoneEditorState.selectedId=id;zoneEditorState.points=[];setZoneDrawMode('select');renderZoneEditor();toast('New AI zone added. Configure its rules on the right.')}
function cancelZoneDrawing(){zoneEditorState.points=[];setZoneDrawMode('select');renderDraftPoints()}
function zoneColor(type){return (ZONE_TYPES[type]||ZONE_TYPES.Custom).color}
function renderZoneSvg(svg){const poly=zoneEditorState.zones.map(z=>{const selected=z.id===zoneEditorState.selectedId;const points=z.points.map(p=>`${p[0]*10},${p[1]*5.6}`).join(' ');const cx=z.points.reduce((a,p)=>a+p[0],0)/z.points.length*10,cy=z.points.reduce((a,p)=>a+p[1],0)/z.points.length*5.6;return `<g class="zone-svg-item" onclick="selectZone('${z.id}');event.stopPropagation()"><polygon points="${points}" fill="${zoneColor(z.type)}22" stroke="${zoneColor(z.type)}" stroke-width="${selected?5:3}" stroke-dasharray="${z.type==='Ignore Zone'?'8 6':'0'}"></polygon><rect x="${Math.max(5,cx-65)}" y="${Math.max(18,cy-20)}" width="130" height="24" rx="7" fill="${zoneColor(z.type)}"></rect><text x="${cx}" y="${Math.max(34,cy-4)}" text-anchor="middle" fill="#fff" font-size="13" font-weight="700">${z.name.slice(0,20)}</text></g>`}).join('');const lines=zoneEditorState.lines.map(l=>{const a=l.points[0],b=l.points[1];return `<g><line x1="${a[0]*10}" y1="${a[1]*5.6}" x2="${b[0]*10}" y2="${b[1]*5.6}" stroke="#3de08b" stroke-width="5" marker-end="url(#arrow)"></line><text x="${((a[0]+b[0])/2)*10}" y="${((a[1]+b[1])/2)*5.6-10}" fill="#9fffd5" font-size="13" text-anchor="middle">ENTRY / EXIT</text></g>`}).join('');const cal=zoneEditorState.calibration.length===4?`<polygon points="${zoneEditorState.calibration.map(p=>`${p[0]*10},${p[1]*5.6}`).join(' ')}" fill="#ffffff08" stroke="#ffffff88" stroke-width="2" stroke-dasharray="6 6"></polygon>`:'';const draft=zoneEditorState.points.length>1?`<polyline points="${zoneEditorState.points.map(p=>`${p[0]*10},${p[1]*5.6}`).join(' ')}" fill="none" stroke="#fff" stroke-width="3" stroke-dasharray="5 5"></polyline>`:'';svg.innerHTML=`<defs><marker id="arrow" markerWidth="10" markerHeight="10" refX="8" refY="3" orient="auto"><path d="M0,0 L0,6 L9,3 z" fill="#3de08b"></path></marker></defs>${poly}${lines}${cal}${draft}`}
function renderZoneEditor(){const svg=document.getElementById('zoneSvg');if(svg)renderZoneSvg(svg);const list=document.getElementById('zoneList');if(list){list.innerHTML=`<div class="zone-quick-add"><select class="select" id="newZoneTypeQuick">${Object.keys(ZONE_TYPES).map(t=>`<option>${t}</option>`).join('')}</select><small>Choose type, then draw polygon/rectangle on camera.</small></div>`+zoneEditorState.zones.map(z=>`<button class="zone-list-btn ${z.id===zoneEditorState.selectedId?'active':''}" onclick="selectZone('${z.id}')"><span class="zone-swatch" style="background:${zoneColor(z.type)}"></span><span><b>${z.name}</b><small>${z.type} · ${z.schedule}</small></span></button>`).join('')+zoneEditorState.lines.map(l=>`<button class="zone-list-btn"><span class="zone-swatch" style="background:#3de08b"></span><span><b>${l.name}</b><small>Directional counting line</small></span></button>`).join('')}const badgeEl=document.getElementById('zoneCountBadge');if(badgeEl)badgeEl.textContent=`${zoneEditorState.zones.length} zones · ${zoneEditorState.lines.length} lines`;renderZoneSettings();renderDraftPoints()}
function selectZone(id){zoneEditorState.selectedId=id;renderZoneEditor()}
function renderZoneSettings(){const p=document.getElementById('zoneSettingsPanel');if(!p)return;const z=zoneEditorState.zones.find(x=>x.id===zoneEditorState.selectedId);if(!z){p.innerHTML='<div class="zone-empty">Select a zone to configure sensitivity, schedule, rules and business links.</div>';return}const allRules=[...new Set(Object.values(ZONE_TYPES).flatMap(x=>x.rules))];p.innerHTML=`<div class="field"><label>Zone Name</label><input class="input" id="zsName" value="${z.name}" onchange="updateSelectedZoneSettings()"></div><div class="form-grid compact"><div class="field"><label>Zone Type</label><select class="select" id="zsType" onchange="changeSelectedZoneType()">${Object.keys(ZONE_TYPES).map(t=>`<option ${t===z.type?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label>Preset</label><select class="select" id="zsPreset" onchange="applySelectedPreset()">${[...new Set(Object.values(ZONE_TYPES).map(x=>x.preset))].map(x=>`<option ${x===z.preset?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Sensitivity</label><select class="select" id="zsSensitivity" onchange="updateSelectedZoneSettings()"><option ${z.sensitivity==='Low'?'selected':''}>Low</option><option ${z.sensitivity==='Medium'?'selected':''}>Medium</option><option ${z.sensitivity==='High'?'selected':''}>High</option><option ${z.sensitivity==='Custom'?'selected':''}>Custom</option></select></div><div class="field"><label>Schedule</label><select class="select" id="zsSchedule" onchange="updateSelectedZoneSettings()"><option ${z.schedule==='Always'?'selected':''}>Always</option><option ${z.schedule==='Shop Hours'?'selected':''}>Shop Hours</option><option ${z.schedule==='Owner Away Only'?'selected':''}>Owner Away Only</option><option ${z.schedule==='After Hours'?'selected':''}>After Hours</option><option ${z.schedule==='Custom'?'selected':''}>Custom</option></select></div><div class="field"><label>Trigger Delay</label><select class="select" id="zsDelay" onchange="updateSelectedZoneSettings()"><option ${z.delay==='Immediate'?'selected':''}>Immediate</option><option ${z.delay==='10 sec'?'selected':''}>10 sec</option><option ${z.delay==='30 sec'?'selected':''}>30 sec</option><option ${z.delay==='1 min'?'selected':''}>1 min</option><option ${z.delay==='3 min'?'selected':''}>3 min</option></select></div><div class="field"><label>Recording</label><select class="select" id="zsRecord" onchange="updateSelectedZoneSettings()"><option ${z.record==='AI events + buffer'?'selected':''}>AI events + buffer</option><option ${z.record==='Events only'?'selected':''}>Events only</option><option ${z.record==='Continuous'?'selected':''}>Continuous</option><option ${z.record==='Monitoring only'?'selected':''}>Monitoring only</option></select></div></div><h4>Business Links</h4><div class="form-grid compact"><div class="field"><label>Inventory Shelf / Rack</label><select class="select" id="zsShelf" onchange="updateSelectedZoneSettings()">${['Not linked','Counter Stock','Rack A · Shelf 2','Rack B · Shelf 1','High Value Rack','Cold Storage'].map(x=>`<option ${x===z.shelf?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>POS Counter</label><select class="select" id="zsPos" onchange="updateSelectedZoneSettings()">${['Not linked','Counter 1','Counter 2'].map(x=>`<option ${x===z.pos?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Cash Drawer</label><select class="select" id="zsDrawer" onchange="updateSelectedZoneSettings()">${['Not linked','Drawer 1','Drawer 2'].map(x=>`<option ${x===z.drawer?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Employee Context</label><select class="select"><option>Use shift + POS login</option><option>Counter assignment only</option><option>Anonymous only</option></select></div></div><h4>Rules in this Zone</h4><div class="zone-rule-grid">${allRules.map(r=>`<label><input type="checkbox" value="${r}" ${z.rules.includes(r)?'checked':''} onchange="updateSelectedZoneRules()"> ${r}</label>`).join('')}</div>`}
function updateSelectedZoneSettings(){const z=zoneEditorState.zones.find(x=>x.id===zoneEditorState.selectedId);if(!z)return;const v=id=>document.getElementById(id)?.value;z.name=v('zsName')||z.name;z.type=v('zsType')||z.type;z.preset=v('zsPreset')||z.preset;z.sensitivity=v('zsSensitivity')||z.sensitivity;z.schedule=v('zsSchedule')||z.schedule;z.delay=v('zsDelay')||z.delay;z.record=v('zsRecord')||z.record;z.shelf=v('zsShelf')||z.shelf;z.pos=v('zsPos')||z.pos;z.drawer=v('zsDrawer')||z.drawer;renderZoneEditor()}
function updateSelectedZoneRules(){const z=zoneEditorState.zones.find(x=>x.id===zoneEditorState.selectedId);if(!z)return;z.rules=[...document.querySelectorAll('.zone-rule-grid input:checked')].map(x=>x.value)}
function changeSelectedZoneType(){const z=zoneEditorState.zones.find(x=>x.id===zoneEditorState.selectedId);if(!z)return;z.type=document.getElementById('zsType').value;const meta=ZONE_TYPES[z.type]||ZONE_TYPES.Custom;z.preset=meta.preset;z.rules=[...meta.rules];renderZoneEditor()}
function applySelectedPreset(){const z=zoneEditorState.zones.find(x=>x.id===zoneEditorState.selectedId);if(!z)return;const preset=document.getElementById('zsPreset').value;const meta=Object.values(ZONE_TYPES).find(x=>x.preset===preset);z.preset=preset;if(meta)z.rules=[...meta.rules];renderZoneEditor();toast('Preset rules applied')}
function deleteSelectedZone(){if(!zoneEditorState.selectedId)return toast('Select a zone first.');zoneEditorState.zones=zoneEditorState.zones.filter(z=>z.id!==zoneEditorState.selectedId);zoneEditorState.selectedId=zoneEditorState.zones[0]?.id||null;renderZoneEditor();toast('Zone removed from current draft')}
function polygonCentroid(points){return [points.reduce((a,p)=>a+p[0],0)/points.length,points.reduce((a,p)=>a+p[1],0)/points.length]}
function testSelectedZone(){const z=zoneEditorState.zones.find(x=>x.id===zoneEditorState.selectedId);if(!z)return toast('Select a zone first.');const c=document.getElementById('zoneCanvas');if(!c)return;document.querySelector('.zone-test-person')?.remove();const [x,y]=polygonCentroid(z.points);const d=document.createElement('div');d.className='zone-test-person';d.style.left=`${x}%`;d.style.top=`${y}%`;d.innerHTML='<span>TEST PERSON</span>';c.appendChild(d);const s=document.getElementById('zoneTestStatus');if(s)s.innerHTML=`<b style="color:var(--success)">PASS</b> · ${z.name} detected · ${z.rules.length} rule(s) active`;setTimeout(()=>d.remove(),3200)}
function runZoneCalibrationTest(){if(zoneEditorState.calibration.length===4)toast('Calibration test passed · perspective reference saved in demo.');else{setZoneDrawMode('calibrate');toast('Click 4 floor reference points on the camera preview.') }}
function saveZoneConfiguration(){localStorage.setItem('medguard-zones-'+zoneEditorState.camera,JSON.stringify({zones:zoneEditorState.zones,lines:zoneEditorState.lines,calibration:zoneEditorState.calibration}));closeModal();toast(`${zoneEditorState.zones.length} AI zones + ${zoneEditorState.lines.length} line(s) saved for ${zoneEditorState.camera}`)}
function simulateRuleHistory(name){openModal('Rule Simulation · '+name,`<div class="hero-sim"><b>Last 7 Days Simulation</b><span>Historical demo events only</span></div><div class="grid grid-4">${metric('⚠','Would Trigger','17')}${metric('✓','Likely Useful','12')}${metric('×','Likely Noise','5')}${metric('⏱','Est. Alerts / Day','2.4')}</div><div class="notice-card"><b>Suggested tuning</b><span>Increase trigger delay to 30 seconds and keep a 5-minute cooldown to reduce repeated alerts from one continuous event.</span></div>`,`<button class="btn secondary" onclick="closeModal()">Close</button><button class="btn primary" onclick="toast('Suggested thresholds applied to demo')">Apply Suggested Tuning</button>`)}
function setReviewFeedback(type){const map={normal:'Marked Normal — legitimate activity after human review.',investigate:'Saved for further investigation and evidence retention.',false:'Marked False Alert — use this feedback to tune the rule.'};toast(map[type]||'Review updated')}
function createIncidentCase(ev){openModal('Create Incident Case',`<div class="form-grid"><div class="field"><label>Case ID</label><input class="input" value="INC-0024"></div><div class="field"><label>Source Event</label><input class="input" value="${ev}" readonly></div><div class="field"><label>Priority</label><select class="select"><option>High</option><option>Medium</option><option>Critical</option></select></div><div class="field"><label>Assign To</label><select class="select"><option>Owner Admin</option><option>Manager</option></select></div><div class="field" style="grid-column:1/-1"><label>Case Title</label><input class="input" value="Cash drawer / transaction mismatch review"></div><div class="field" style="grid-column:1/-1"><label>Notes</label><textarea class="textarea">Review related transaction, payment confirmation and camera clip before any conclusion.</textarea></div></div><div class="connector-data"><label><input type="checkbox" checked> Include CCTV clip</label><label><input type="checkbox" checked> Include transaction timeline</label><label><input type="checkbox" checked> Include payment evidence</label><label><input type="checkbox" checked> Include inventory evidence</label></div>`,`<button class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="closeModal();toast('Incident case INC-0024 created')">Create Case</button>`)}
function showIncidentCases(){openModal('Incident Cases',`<div class="check-card"><div><b>INC-0023 · Inventory discrepancy</b><br><span>3 related events · 2 transactions · Owner Admin</span></div>${badge('Open','warning')}</div><div class="check-card"><div><b>INC-0022 · Payment mismatch</b><br><span>1 event · UPI confirmation later matched</span></div>${badge('Resolved','success')}</div>`,`<button class="btn primary" onclick="closeModal()">Done</button>`)}
function showShiftReconcile(){openModal('Close / Reconcile Shift',`<div class="form-grid"><div class="field"><label>Shift</label><select class="select"><option>Evening · 3:00–9:00</option><option>Morning · 9:00–3:00</option></select></div><div class="field"><label>Counter</label><select class="select"><option>Counter 1</option><option>Counter 2</option></select></div><div class="field"><label>Expected Cash</label><input class="input" value="₹36,200" readonly></div><div class="field"><label>Counted Cash</label><input class="input" value="₹35,650"></div><div class="field"><label>Cash Expenses</label><input class="input" value="₹0"></div><div class="field"><label>Difference</label><input class="input" value="₹550 Short" readonly></div></div><div class="notice-card"><b>AI investigation helper</b><span>If a difference remains, the system can shortlist drawer anomalies, cancellations and unmatched transactions from only this shift.</span></div>`,`<button class="btn secondary" onclick="toast('2 review events shortlisted for this shift')">Investigate Difference</button><button class="btn primary" onclick="closeModal();toast('Shift reconciliation saved')">Save Shift Closing</button>`)}
function showShelfMapping(){openModal('Medicine Rack ↔ Camera Zone Mapping',`<div class="card flush"><div class="table-wrap"><table class="table"><thead><tr><th>Inventory Location</th><th>Camera</th><th>AI Zone</th><th>Products</th></tr></thead><tbody><tr><td><b>Rack A · Shelf 2</b></td><td>Medicine Shelves</td><td>Zone A2</td><td>126 SKUs</td></tr><tr><td><b>Rack B · Shelf 1</b></td><td>Medicine Shelves</td><td>Zone B1</td><td>94 SKUs</td></tr><tr><td><b>High Value Rack</b></td><td>Storage Room</td><td>Secure Zone</td><td>38 SKUs</td></tr><tr><td><b>Cold Storage</b></td><td>Storage Room</td><td>Cold Zone</td><td>27 SKUs</td></tr></tbody></table></div></div><div class="form-grid" style="margin-top:14px"><div class="field"><label>Inventory Location</label><select class="select"><option>Rack C · Shelf 3</option><option>Rack A · Shelf 1</option></select></div><div class="field"><label>Camera Zone</label><select class="select"><option>Medicine Shelves → Zone C3</option><option>Storage Room → Secure Zone</option></select></div></div>`,`<button class="btn primary" onclick="closeModal();toast('Shelf mapping saved')">Save Mapping</button>`)}
function showHighRiskConfig(){openModal('High-Risk Medicine Monitoring',`<div class="form-grid"><div class="field"><label>Medicine / Category</label><input class="input" placeholder="Search medicine or category"></div><div class="field"><label>Risk Class</label><select class="select"><option>High Value</option><option>High Shrinkage Risk</option><option>Restricted Storage</option><option>Cold Storage</option></select></div><div class="field"><label>Inventory Location</label><select class="select"><option>High Value Rack</option><option>Cold Storage</option><option>Rack A · Shelf 2</option></select></div><div class="field"><label>Monitoring</label><select class="select"><option>Strict during Owner Away</option><option>Always enhanced</option><option>Shop hours only</option></select></div></div><div class="connector-data"><label><input type="checkbox" checked> Compare with billed sale</label><label><input type="checkbox" checked> Compare with stock movement</label><label><input type="checkbox" checked> Save review clip</label><label><input type="checkbox"> Immediate owner alert</label></div>`,`<button class="btn primary" onclick="closeModal();toast('High-risk medicine rule saved')">Save Monitoring Rule</button>`)}

function setupPage(){document.body.innerHTML=`<div class="setup-page"><div class="setup-shell"><aside class="setup-side"><div class="brand" style="padding:0 0 16px;border-bottom-color:rgba(255,255,255,.08)"><div class="brand-mark">M</div><div><h1>MedGuard AI</h1><p>First-Time Setup</p></div></div>${['Shop Details','Network','Cameras','Billing / POS','Inventory','Payments','Storage','Notifications','AI Rules','System Test'].map((s,i)=>`<div class="step ${i===0?'active':''}"><div class="step-num">${i+1}</div><span>${s}</span></div>`).join('')}</aside><main class="setup-main" id="setupMain"><h1>Welcome to MedGuard AI</h1><p>Configure your medical shop step by step. This frontend wizard simulates the final onboarding experience.</p><div class="form-grid"><div class="field"><label>Medical Shop Name</label><input class="input" value="Main Medical Store"></div><div class="field"><label>Branch Name</label><input class="input" value="Main Branch"></div><div class="field"><label>Owner Name</label><input class="input" value="Owner Admin"></div><div class="field"><label>City</label><input class="input" value="Yavatmal"></div><div class="field"><label>Opening Time</label><input class="input" type="time" value="09:00"></div><div class="field"><label>Closing Time</label><input class="input" type="time" value="21:00"></div></div><div style="display:flex;justify-content:flex-end;margin-top:24px"><button class="btn primary" onclick="setupNext()">Continue Setup →</button></div></main></div></div><div class="toast-wrap" id="toastWrap"></div>`}
let setupStep=0;function setupNext(){setupStep++;const steps=document.querySelectorAll('.step');steps.forEach((s,i)=>{s.classList.toggle('active',i===setupStep);if(i<setupStep)s.classList.add('done')});const names=['Shop Details','Network','Cameras','Billing / POS','Inventory','Payments','Storage','Notifications','AI Rules','System Test'];const main=document.getElementById('setupMain');if(setupStep>=9){main.innerHTML=`<h1>Full System Test</h1><p>All configured components will be checked before AI monitoring starts.</p>${['Local Network','Cameras','Billing / POS','Inventory','Payments','Database','Storage','AI Engine','Owner Notifications'].map(x=>`<div class="check-card"><div><b>${x}</b><br><span>Connection and health check</span></div>${badge('PASS','success')}</div>`).join('')}<div style="display:flex;justify-content:flex-end;margin-top:18px"><a href="dashboard.html" class="btn success">Start AI Supervisor ✓</a></div>`;return}const name=names[setupStep];main.innerHTML=`<h1>${name}</h1><p>Configure ${name.toLowerCase()} for this medical shop. Detailed production fields can be refined after reviewing this frontend.</p><div class="check-card"><div><b>${name} Connection</b><br><span>Recommended automatic configuration</span></div>${badge('Ready','success')}</div><div class="form-grid" style="margin-top:14px"><div class="field"><label>Configuration Mode</label><select class="select"><option>Automatic / Recommended</option><option>Manual</option></select></div><div class="field"><label>Connection Name</label><input class="input" value="Main ${name}"></div><div class="field" style="grid-column:1/-1"><label>Configuration Notes</label><textarea class="textarea">Configure ${name} integration for Main Medical Store.</textarea></div></div><div style="display:flex;justify-content:space-between;margin-top:24px"><button class="btn secondary" onclick="setupBack()">← Back</button><button class="btn primary" onclick="setupNext()">Continue →</button></div>`}
function setupBack(){if(setupStep<=0)return;setupStep-=2;setupNext()}
function loginPage(){document.body.innerHTML=`<div class="login-page"><section class="login-visual"><div><div class="brand" style="padding:0;border:0"><div class="brand-mark">M</div><div><h1>ITCYBER MedGuard AI</h1><p>Medical Shop Supervisor</p></div></div></div><div><h1>Know what is happening in your medical shop — even when you are away.</h1><p>One dashboard for cameras, sales, cash, UPI, inventory, review events and AI-generated operational intelligence.</p><div class="login-benefits"><div class="benefit">◉ Multi-camera AI monitoring</div><div class="benefit">₹ Payment reconciliation</div><div class="benefit">⚠ Evidence-based review events</div></div></div><div style="font-size:10px;color:#8094ad">Frontend Prototype · No live camera or financial data is connected yet.</div></section><section class="login-panel"><div class="login-box"><div class="brand" style="padding:0 0 18px;border:0;color:var(--text)"><div class="brand-mark">M</div><div><h1 style="color:var(--text)">Welcome back</h1><p>Secure owner & staff access</p></div></div><h2>Sign in</h2><p>Use the prototype credentials or continue directly.</p><div class="field"><label>Email / Username</label><input class="input" value="owner@shop.local"></div><div class="field"><label>Password</label><input class="input" type="password" value="password"></div><div style="display:flex;justify-content:space-between;font-size:10px;color:var(--muted);margin:8px 0 16px"><label><input type="checkbox" checked> Remember me</label><span>Forgot password?</span></div><button class="btn primary" onclick="location.href='dashboard.html'">Sign In</button><a href="setup.html" class="btn secondary" style="margin-top:8px">Run First-Time Setup</a><div class="login-foot">Protected access · Role-based permissions · Audit logging</div></div></section></div>`}
function init(){const page=document.body.dataset.page||'dashboard';if(page==='login')return loginPage();if(page==='setup')return setupPage();const pages={dashboard:pageDashboard,live:pageLive,cameras:pageCameras,events:pageEvents,investigation:pageInvestigation,sales:pageSales,payments:pagePayments,inventory:pageInventory,employees:pageEmployees,ai:pageAI,reports:pageReports,connections:pageConnections,rules:pageRules,alerts:pageAlerts,users:pageUsers,health:pageHealth,settings:pageSettings};shell(page,(pages[page]||pageDashboard)(),page==='investigation'?'events':page);}
document.addEventListener('DOMContentLoaded',init);
